def O_mean(theta, N, beta):
    """Deterministic order parameter (N->inf Gaussian limit of majority vote)."""
    arg = sqrt(N / 2.0) * sinh(beta * theta)
    return erf(arg)

def g_func(theta, N, beta):
    """Derivative of O_mean w.r.t. theta."""
    arg = sqrt(N / 2.0) * sinh(beta * theta)
    darg_dtheta = sqrt(N / 2.0) * beta * cosh(beta * theta)
    return (2.0 / sqrt(pi)) * exp(-arg**2) * darg_dtheta

